SELECT
    h.field_id, h.field_task_id, m.field_name AS field_task_name,
    h.field_result, h.field_start_time, h.field_end_time,
    h.field_group, h.field_params, h.field_log
FROM sys_task_history h
LEFT JOIN sys_task_main m ON m.field_id = h.field_task_id

    AND m.field_name LIKE CONCAT('%', #{model.fieldTaskName}, '%')
    AND h.field_result = #{model.fieldResult}
    AND h.field_start_time >= #{model.fieldStartTimeStart}
    AND h.field_start_time <= #{model.fieldStartTimeEnd}
    AND h.field_end_time >= #{model.fieldEndTimeStart}
    AND h.field_end_time <= #{model.fieldEndTimeEnd}

ORDER BY

    h.field_start_time
    h.field_end_time
    h.field_start_time


    ASC
    DESC



    LIMIT #{pages.pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM sys_task_history h
LEFT JOIN sys_task_main m ON m.field_id = h.field_task_id

    AND m.field_name LIKE CONCAT('%', #{model.fieldTaskName}, '%')
    AND h.field_result = #{model.fieldResult}
    AND h.field_start_time >= #{model.fieldStartTimeStart}
